func SafelyAdvanceLocalRef(ctx context.Context, repo *git.Repository, localRefName plumbing.ReferenceName, targetHash plumbing.Hash) error {
	currentLocal, localErr := repo.Reference(localRefName, true)
	if localErr == nil {
