func resolveRefHash(repo *git.Repository, refName string) (plumbing.Hash, error) {
	ref, err := repo.Reference(plumbing.ReferenceName(refName), true)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("ref %s not found: %w", refName, err)
	}
	return ref.Hash(), nil
}

